const pack = (id, title, first, second, takeaway, exercise, checks) => ({ id, title, paragraphs: [first, second], takeaway, exercise, checks });
function unit(meta, packs) {
  return {
    countries: ["DE", "AT", "CH"], minutes: 45, level: "Aufbau", ...meta,
    lessons: packs.map(({ checks, ...lesson }) => lesson),
    questions: packs.flatMap((lesson, index) => lesson.checks.map((item, questionIndex) => {
      const answer = (index * 2 + questionIndex) % 4;
      const options = [...item.options];
      const right = options.shift();
      options.splice(answer, 0, right);
      return { id: `${lesson.id}-${questionIndex + 1}`, lessonId: lesson.id, q: item.q, options, answer, explain: item.explain };
    })),
  };
}

